import { test } from "node:test";
import assert from "node:assert/strict";
import { Keyring } from "../src/crypto/keyring.ts";
import { DecryptError, FieldCipher, parseEnvelope } from "../src/crypto/fieldCipher.ts";
import { ClinicalNotes, type NoteStore, type StoredNote } from "../src/notes/clinicalNotes.ts";

const KEY_2025 = Buffer.alloc(32, 0x25);
const KEY_2026 = Buffer.alloc(32, 0x26);

// Each app replica (or each restart of one) builds its own keyring and cipher from the same key material.
const replica = (active = "dek-2025") => new FieldCipher(new Keyring({ "dek-2025": KEY_2025, "dek-2026": KEY_2026 }, active));

function memoryStore(): NoteStore & { rows: Map<string, StoredNote> } {
    const rows = new Map<string, StoredNote>();
    return { rows, put: async (n) => void rows.set(n.id, { ...n }), get: async (id) => rows.get(id) ?? null, all: async () => [...rows.values()] };
}

const meta = (id: string, patientId = "p-100") => ({ id, patientId, authorId: "dr-okafor", createdAt: "2026-11-19T09:00:00Z" });

test("a note reads back and is never stored in plaintext", async () => {
    const store = memoryStore();
    const notes = new ClinicalNotes(store, replica());
    await notes.write(meta("n1"), "Patient reports chest pain on exertion.");
    assert.equal(await notes.read("n1"), "Patient reports chest pain on exertion.");
    assert.ok(!store.rows.get("n1")!.body.includes("chest"));
    assert.equal(parseEnvelope(store.rows.get("n1")!.body).kid, "dek-2025");
});

test("a tampered note body is rejected instead of returning garbage", async () => {
    const store = memoryStore();
    const notes = new ClinicalNotes(store, replica());
    await notes.write(meta("n1"), "BP 120/80");
    const parts = store.rows.get("n1")!.body.split(".");
    const ct = Buffer.from(parts[4], "base64url");
    ct[0] ^= 0x01;
    parts[4] = ct.toString("base64url");
    store.rows.get("n1")!.body = parts.join(".");
    await assert.rejects(notes.read("n1"), DecryptError);
});

test("a note body copied onto another patient's record does not decrypt", async () => {
    const store = memoryStore();
    const notes = new ClinicalNotes(store, replica());
    await notes.write(meta("n1", "p-100"), "HIV positive, started ART.");
    await notes.write(meta("n2", "p-200"), "Seasonal allergies.");
    store.rows.get("n2")!.body = store.rows.get("n1")!.body;
    await assert.rejects(notes.read("n2"), DecryptError);
});

test("after a key rotation old notes still read and the re-encryption job moves them to the new key", async () => {
    const store = memoryStore();
    await new ClinicalNotes(store, replica("dek-2025")).write(meta("n1"), "Follow up in 2 weeks.");
    const rotated = new ClinicalNotes(store, replica("dek-2026"));
    assert.equal(await rotated.read("n1"), "Follow up in 2 weeks.");
    assert.equal(await rotated.reencryptAll(), 1);
    assert.equal(parseEnvelope(store.rows.get("n1")!.body).kid, "dek-2026");
    assert.equal(await rotated.read("n1"), "Follow up in 2 weeks.");
    assert.equal(await rotated.reencryptAll(), 0);
});

test("two replicas encrypting with the same key never use the same nonce", () => {
    const a = replica();
    const b = replica();
    const nonces = [a, b, a, b].map((c, i) => parseEnvelope(c.encrypt(`note ${i}`, "aad")).nonce.toString("hex"));
    console.log("nonces from replicas a, b, a, b:", nonces);
    assert.equal(new Set(nonces).size, nonces.length);
});

test("a note written after a restart does not leak the plaintext of a note written before it", () => {
    const before = "Diagnosis: type 2 diabetes";
    const after = "Diagnosis: none, healthy.";
    const c1 = parseEnvelope(replica().encrypt(before, "aad")).ciphertext;
    const c2 = parseEnvelope(replica().encrypt(after, "aad")).ciphertext;
    // With a repeated nonce, GCM's keystream cancels out: c1 ^ c2 === p1 ^ p2.
    const xor = (x: Buffer, y: Buffer) => Buffer.from(x.subarray(0, Math.min(x.length, y.length)).map((v, i) => v ^ y[i]));
    assert.notDeepEqual(xor(c1, c2), xor(Buffer.from(before), Buffer.from(after)));
});

test("notes written by several replicas all have distinct nonces in storage", async () => {
    const store = memoryStore();
    const replicas = [new ClinicalNotes(store, replica()), new ClinicalNotes(store, replica()), new ClinicalNotes(store, replica())];
    for (let i = 0; i < 9; i++) await replicas[i % 3].write(meta(`n${i}`, `p-${i}`), `visit summary ${i}`);
    const nonces = [...store.rows.values()].map((n) => parseEnvelope(n.body).nonce.toString("hex"));
    assert.equal(new Set(nonces).size, 9);
    for (let i = 0; i < 9; i++) assert.equal(await replicas[(i + 1) % 3].read(`n${i}`), `visit summary ${i}`);
});
